/// ---------------------------------------------------------------------------
/// Dedicated Brand Logo Avatar Widget
/// Renders the authentic official vector SVG brand badge edge-to-edge with
/// crisp anti-aliasing, rounded corners, and brand-tinted subtle shadow.
/// ---------------------------------------------------------------------------
class BrandLogoWidget extends StatelessWidget {
  final String brand;
  final String model;
  final double size;
  final double borderRadius;
  final bool showBorder;

  const BrandLogoWidget({
    super.key,
    required this.brand,
    this.model = '',
    this.size = 46.0,
    this.borderRadius = 13.0,
    this.showBorder = false,
  });

  @override
  Widget build(BuildContext context) {
    final info = BrandSvgLogos.getBrandInfo(brand, model);

    return Container(
      width: size,
      height: size,
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(borderRadius),
        border: showBorder
            ? Border.all(
                color: info.primaryColor.withValues(alpha: 0.3),
                width: 1.0,
              )
            : null,
        boxShadow: [
          BoxShadow(
            color: info.primaryColor.withValues(alpha: 0.16),
            blurRadius: 8,
            offset: const Offset(0, 3),
          ),
        ],
      ),
      child: ClipRRect(
        borderRadius: BorderRadius.circular(borderRadius - 0.5),
        child: SvgPicture.string(
          info.svgString,
          width: size,
          height: size,
          fit: BoxFit.cover,
        ),
      ),
    );
  }
}
